	/**
	 * この画面を埋め込み画面として作成します。
	 */
	public static MABCP_MultiReg create(){
		MABCP_MultiReg p = new MABCP_MultiReg();
		p.jbCreate();
		setParts(p);
		p.appInit();
		return p;
	}

	/**
	 * この画面を埋め込み画面として作成します。
	 */
	public static MABCP_MultiReg create(String name){
		MABCP_MultiReg p = new MABCP_MultiReg(name);
		p.jbCreate();
		setParts(p);
		p.appInit();
		return p;
	}

